import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let n be an integer with n > 2. Real numbers a_1, a_2, ..., a_{n} satisfy the constraints sum_{k=1}^{n} a_k = {sum_linear} and sum_{k=1}^{n} k |a_k| = {weighted_sum_target}. Determine the exact minimum value of a_1^2 + a_2^2 + ... + a_n^2.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    from fractions import Fraction

def generator(rng):
    # We generate parameters so that the optimizer has a structured, nontrivial solution.
    # Construction: choose an integer t >= 4 and d >= 2, set
    #   S = d * t(t-1)/2, U = d * t(t-1)(t+1)/6, and pick n >= t+1.
    # Then the minimizing configuration is a_k = d * max(t - k, 0),
    # which uses exactly t-1 active coordinates (strictly less than n).
    # This ensures nontriviality and integrality.
    while True:
        t = rng.randint(4, 8)  # ensures at least 3 active variables and manageable sizes
        # ensure n strictly exceeds the active set size (t-1)
        n = rng.randint(t+1, t+9)
        d = rng.randint(2, 9)
        # Compute S and U as integers
        S = d * (t * (t - 1) // 2)
        # t(t-1)(t+1)/6 is integer (product of 3 consecutive integers)
        U = d * (t * (t - 1) * (t + 1) // 6)
        # Sanity checks (nontriviality): ensure S,U > 0 and t <= n+1
        if S > 0 and U > 0 and t <= n + 1:
            return {
                'n': n,
                'sum_linear': S,
                'weighted_sum_target': U
            }
        # else retry

    from fractions import Fraction

# The minimum is attained by a_k = c * max(t - k, 0), where t = 3U/S - 1,
# c chosen to meet sum constraint. The minimum value is
#   (2 S^2 (2t - 1)) / (3 t (t - 1)).
# We verify parameters imply integer t with 4 <= t <= n+1 and then compute the exact minimum.

def verifier(assign):
    try:
        n = int(assign.get('n', 0))
        S = int(assign.get('sum_linear', 0))
        U = int(assign.get('weighted_sum_target', 0))
    except Exception:
        # invalid types
        return (False, None)

    # Basic domain checks
    if not (isinstance(n, int) and isinstance(S, int) and isinstance(U, int)):
        # Non-integer input detected
        return (False, None)
    if n <= 2 or S <= 0 or U <= 0:
        # Out of domain
        return (False, None)

    # Compute t = 3U/S - 1, must be integer and >= 4, and active set size t-1 <= n
    num = 3 * U
    den = S
    if den == 0 or num % den != 0:
        # t not integral
        return (False, None)
    r = num // den
    t = r - 1
    if t < 4:
        # Too small: would weaken difficulty (fewer than 3 active variables)
        return (False, None)
    if (t - 1) > n:
        # Active set larger than dimension; inconsistent
        return (False, None)

    # Compute exact minimum as a reduced fraction
    # value = (2 S^2 (2t - 1)) / (3 t (t - 1))
    num_val = 2 * S * S * (2 * t - 1)
    den_val = 3 * t * (t - 1)
    min_frac = Fraction(num_val, den_val)

    # Provide exact fraction and decimal for convenience
    answer = {
        't': t,
        'exact': f"{min_frac.numerator}/{min_frac.denominator}",
        'value': float(min_frac)
    }

    return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

